export type OrgId = string;
export type UserId = string;
export type MemberId = string;
export type InvitationId = string;
export type SessionId = string;
export type NotificationId = string;
export type IsoTimestamp = string;

import type { InvitationId, IsoTimestamp, MemberId, OrgId, UserId } from "@/types/common";

export type MemberRole = string;

export type MemberStatus = "active" | "removed";

export type Member = {
  id: MemberId;
  orgId: OrgId;
  userId: UserId;
  email: string | null;
  role: MemberRole;
  status: MemberStatus;
  invitedBy: UserId | null;
  joinedAt: IsoTimestamp;
  lastSeenAt: IsoTimestamp | null;
  removedAt: IsoTimestamp | null;
};

export type Invitation = {
  id: InvitationId;
  orgId: OrgId;
  email: string;
  role: MemberRole;
  token: string;
  invitedBy: UserId;
  expiresAt: IsoTimestamp;
  acceptedAt: IsoTimestamp | null;
  revokedAt: IsoTimestamp | null;
  createdAt: IsoTimestamp;
};

export type InvitationState = "pending" | "accepted" | "revoked" | "expired";

/** Compare mailbox addresses without regard to letter case or surrounding space. */
export function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

import { randomBytes, randomUUID } from "node:crypto";

export function newId(prefix: string): string {
  return `${prefix}_${randomUUID()}`;
}

export function newToken(): string {
  return randomBytes(32).toString("base64url");
}

import type { IsoTimestamp } from "@/types/common";

export const MS_PER_DAY = 24 * 60 * 60 * 1000;

export function toIsoTimestamp(date: Date): IsoTimestamp {
  return date.toISOString();
}

export function addDays(date: Date, days: number): Date {
  return new Date(date.getTime() + days * MS_PER_DAY);
}

/** An invitation is valid for 14 days from the moment it is sent or re-sent. */
export const INVITATION_VALID_DAYS = 14;

const PLAN_SEAT_LIMITS: Record<string, number> = {
  free: 3,
  starter: 3,
  hobby: 3,
  solo: 1,
  pro: 10,
  team: 10,
  business: 25,
  growth: 25,
  enterprise: 100,
};

export function seatLimitForPlan(plan: string | null | undefined): number | null {
  if (!plan) return null;
  const named = PLAN_SEAT_LIMITS[plan.trim().toLowerCase()];
  if (named) return named;
  const match = /(\d+)\s*-?\s*seat/i.exec(plan);
  if (match) return Number(match[1]);
  return null;
}

export class DomainError extends Error {
  readonly code: string;

  constructor(code: string, message: string) {
    super(message);
    this.name = "DomainError";
    this.code = code;
  }
}

export function seatsTaken(): DomainError {
  return new DomainError("seats", "all seats are taken");
}

