import { integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";

export const users = sqliteTable("users", {
  id: text("id").primaryKey(),
  email: text("email").notNull(),
  name: text("name"),
});

export const organizations = sqliteTable("organizations", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  slug: text("slug").notNull(),
  seatLimit: integer("seat_limit"),
  plan: text("plan"),
  ownerId: text("owner_id"),
  deletedAt: text("deleted_at"),
  createdAt: text("created_at").notNull(),
});

export const members = sqliteTable(
  "members",
  {
    id: text("id").primaryKey(),
    orgId: text("org_id").notNull(),
    userId: text("user_id").notNull(),
    email: text("email"),
    role: text("role").notNull(),
    status: text("status").notNull(),
    invitedBy: text("invited_by"),
    joinedAt: text("joined_at").notNull(),
    lastSeenAt: text("last_seen_at"),
    removedAt: text("removed_at"),
  },
  (table) => [uniqueIndex("members_org_user_unique").on(table.orgId, table.userId)],
);

export const invitations = sqliteTable("invitations", {
  id: text("id").primaryKey(),
  orgId: text("org_id").notNull(),
  email: text("email").notNull(),
  role: text("role").notNull(),
  token: text("token").notNull().unique(),
  invitedBy: text("invited_by").notNull(),
  expiresAt: text("expires_at").notNull(),
  acceptedAt: text("accepted_at"),
  revokedAt: text("revoked_at"),
  createdAt: text("created_at").notNull(),
});

export const sessions = sqliteTable("sessions", {
  id: text("id").primaryKey(),
  userId: text("user_id").notNull(),
  defaultOrgId: text("default_org_id"),
});

export const notifications = sqliteTable("notifications", {
  id: text("id").primaryKey(),
  orgId: text("org_id").notNull(),
  userId: text("user_id").notNull(),
  kind: text("kind").notNull(),
  payload: text("payload").notNull(),
  createdAt: text("created_at").notNull(),
  readAt: text("read_at"),
});

import { eq, type SQLWrapper } from "drizzle-orm";
import type { AnyColumn } from "drizzle-orm";

import type { OrgId } from "@/types/common";

export function orgPredicate(column: AnyColumn | SQLWrapper, orgId: OrgId) {
  return eq(column as AnyColumn, orgId);
}

import { AsyncLocalStorage } from "node:async_hooks";

import Database from "better-sqlite3";
import { drizzle } from "drizzle-orm/better-sqlite3";

import * as schema from "@/server/db/schema";

type DatabaseInstance = Database.Database;
type AppDb = ReturnType<typeof drizzle<typeof schema>>;

const storage = new AsyncLocalStorage<AppDb>();

let root: AppDb | null = null;
let sqlite: DatabaseInstance | null = null;

const SCHEMA_SQL = `
CREATE TABLE IF NOT EXISTS users (
  id text PRIMARY KEY NOT NULL,
  email text NOT NULL,
  name text
);
CREATE TABLE IF NOT EXISTS organizations (
  id text PRIMARY KEY NOT NULL,
  name text NOT NULL,
  slug text NOT NULL,
  seat_limit integer,
  plan text,
  owner_id text,
  deleted_at text,
  created_at text NOT NULL
);
CREATE TABLE IF NOT EXISTS members (
  id text PRIMARY KEY NOT NULL,
  org_id text NOT NULL,
  user_id text NOT NULL,
  email text,
  role text NOT NULL,
  status text NOT NULL,
  invited_by text,
  joined_at text NOT NULL,
  last_seen_at text,
  removed_at text
);
CREATE UNIQUE INDEX IF NOT EXISTS members_org_user_unique ON members (org_id, user_id);
CREATE TABLE IF NOT EXISTS invitations (
  id text PRIMARY KEY NOT NULL,
  org_id text NOT NULL,
  email text NOT NULL,
  role text NOT NULL,
  token text NOT NULL UNIQUE,
  invited_by text NOT NULL,
  expires_at text NOT NULL,
  accepted_at text,
  revoked_at text,
  created_at text NOT NULL
);
CREATE TABLE IF NOT EXISTS sessions (
  id text PRIMARY KEY NOT NULL,
  user_id text NOT NULL,
  default_org_id text
);
CREATE TABLE IF NOT EXISTS notifications (
  id text PRIMARY KEY NOT NULL,
  org_id text NOT NULL,
  user_id text NOT NULL,
  kind text NOT NULL,
  payload text NOT NULL,
  created_at text NOT NULL,
  read_at text
);
`;

function databasePath(): string {
  const configured = process.env.DATABASE_URL;
  if (!configured || configured === ":memory:") return ":memory:";
  if (configured.startsWith("file:")) return configured.slice("file:".length);
  return configured;
}

export function ensureSchema(connection: DatabaseInstance = requireSqlite()): void {
  connection.exec(SCHEMA_SQL);
}

function requireSqlite(): DatabaseInstance {
  if (!sqlite) getRoot();
  return sqlite as DatabaseInstance;
}

function getRoot(): AppDb {
  if (!root || !sqlite) {
    sqlite = new Database(databasePath());
    sqlite.pragma("foreign_keys = ON");
    root = drizzle(sqlite, { schema });
