import { and, count, eq, gt, isNull, sql } from "drizzle-orm";

import { normalizeEmail } from "@/lib/email";
import { newId, newToken } from "@/lib/ids";
import { MS_PER_DAY, toIsoTimestamp } from "@/lib/time";
import { getDb } from "@/server/db/client";
import { orgPredicate } from "@/server/db/predicates";
import { invitations } from "@/server/db/schema";
import type { InvitationId, OrgId, UserId } from "@/types/common";
import type { Invitation, InvitationState, MemberRole } from "@/types/member";

export type NewInvitation = {
  email: string;
  role: MemberRole;
  expiresInDays: number;
  invitedBy: UserId;
  token?: string;
};

function toInvitation(row: typeof invitations.$inferSelect): Invitation {
  return {
    id: row.id,
    orgId: row.orgId,
    email: row.email,
    role: row.role,
    token: row.token,
    invitedBy: row.invitedBy,
    expiresAt: row.expiresAt,
    acceptedAt: row.acceptedAt,
    revokedAt: row.revokedAt,
    createdAt: row.createdAt,
  };
}

function pendingWhere(orgId: OrgId, now: Date) {
  return and(
    orgPredicate(invitations.orgId, orgId),
    isNull(invitations.acceptedAt),
    isNull(invitations.revokedAt),
    gt(invitations.expiresAt, toIsoTimestamp(now)),
  );
}

export function invitationState(invitation: Invitation, now = new Date()): InvitationState {
  if (invitation.acceptedAt) return "accepted";
  if (invitation.revokedAt) return "revoked";
  if (invitation.expiresAt <= toIsoTimestamp(now)) return "expired";
  return "pending";
}

export function insertInvitationSync(orgId: OrgId, input: NewInvitation): Invitation {
  const now = new Date();
  const stamp = toIsoTimestamp(now);
  const expiresAt = toIsoTimestamp(new Date(now.getTime() + input.expiresInDays * MS_PER_DAY));
  const row = getDb()
    .insert(invitations)
    .values({
      id: newId("inv"),
      orgId,
      email: normalizeEmail(input.email),
      role: input.role,
      token: input.token ?? newToken(),
      invitedBy: input.invitedBy,
      expiresAt,
      acceptedAt: null,
      revokedAt: null,
      createdAt: stamp,
    })
    .returning()
    .get();
  return toInvitation(row);
}

export async function insertInvitation(orgId: OrgId, input: NewInvitation): Promise<Invitation> {
  return insertInvitationSync(orgId, input);
}

export function getInvitationSync(invitationId: InvitationId): Invitation | null {
  const row = getDb().select().from(invitations).where(eq(invitations.id, invitationId)).get();
  return row ? toInvitation(row) : null;
}

export function findInvitationByTokenSync(token: string): Invitation | null {
  const row = getDb().select().from(invitations).where(eq(invitations.token, token)).get();
  return row ? toInvitation(row) : null;
}

export function findPendingInvitationByEmailSync(
  orgId: OrgId,
  email: string,
  now = new Date(),
): Invitation | null {
  const row = getDb()
    .select()
    .from(invitations)
    .where(and(pendingWhere(orgId, now), sql`lower(${invitations.email}) = ${normalizeEmail(email)}`))
    .get();
  return row ? toInvitation(row) : null;
}

export function listInvitationsSync(orgId: OrgId): Invitation[] {
  return getDb()
    .select()
    .from(invitations)
    .where(orgPredicate(invitations.orgId, orgId))
    .all()
    .map(toInvitation);
}

export function listPendingInvitationsSync(orgId: OrgId, now = new Date()): Invitation[] {
  return getDb().select().from(invitations).where(pendingWhere(orgId, now)).all().map(toInvitation);
}

/** Pending invites hold a seat, so the seat quota counts them. */
export function countPendingInvitationsSync(orgId: OrgId, now = new Date()): number {
  const row = getDb()
    .select({ value: count() })
    .from(invitations)
    .where(pendingWhere(orgId, now))
    .get();
  return Number(row?.value ?? 0);
}

export async function countPendingInvitations(orgId: OrgId): Promise<number> {
  return countPendingInvitationsSync(orgId);
}

export function revokeInvitationSync(orgId: OrgId, invitationId: InvitationId, now = new Date()): Invitation {
  const stamp = toIsoTimestamp(now);
  const row = getDb()
    .update(invitations)
    .set({ revokedAt: stamp })
    .where(
      and(
        eq(invitations.id, invitationId),
        orgPredicate(invitations.orgId, orgId),
        isNull(invitations.revokedAt),
        isNull(invitations.acceptedAt),
      ),
    )
    .returning()
    .get();
  if (row) return toInvitation(row);
  const existing = getInvitationSync(invitationId);
  if (!existing || existing.orgId !== orgId) {
    throw new Error("Invitation not found");
  }
  return existing;
}

export async function revokeInvitation(orgId: OrgId, invitationId: InvitationId): Promise<Invitation> {
  return revokeInvitationSync(orgId, invitationId);
}

export function markInvitationAcceptedSync(
  invitationId: InvitationId,
  now = new Date(),
): Invitation | null {
  const row = getDb()
    .update(invitations)
    .set({ acceptedAt: toIsoTimestamp(now) })
    .where(and(eq(invitations.id, invitationId), isNull(invitations.acceptedAt), isNull(invitations.revokedAt)))
    .returning()
    .get();
  return row ? toInvitation(row) : null;
}

