import { eq } from "drizzle-orm";

import { seatLimitForPlan } from "@/config/invitations";
import { newId } from "@/lib/ids";
import { toIsoTimestamp } from "@/lib/time";
import { getDb } from "@/server/db/client";
import { organizations } from "@/server/db/schema";
import { clearDefaultOrgSync } from "@/server/repositories/session-repository";
import type { OrgId, UserId } from "@/types/common";

export type Organization = {
  id: OrgId;
  name: string;
  slug: string;
  seatLimit: number | null;
  plan: string | null;
  ownerId: UserId | null;
  deletedAt: string | null;
  createdAt: string;
};

function toOrganization(row: typeof organizations.$inferSelect): Organization {
  return {
    id: row.id,
    name: row.name,
    slug: row.slug,
    seatLimit: row.seatLimit,
    plan: row.plan,
    ownerId: row.ownerId,
    deletedAt: row.deletedAt,
    createdAt: row.createdAt,
  };
}

export function resolveSeatLimit(org: Pick<Organization, "seatLimit" | "plan">): number {
  if (typeof org.seatLimit === "number") return org.seatLimit;
  return seatLimitForPlan(org.plan) ?? Number.POSITIVE_INFINITY;
}

export function insertOrganizationSync(input: {
  id?: OrgId;
  name: string;
  slug: string;
  seatLimit?: number | null;
  plan?: string | null;
  ownerId?: UserId | null;
}): Organization {
  const row = getDb()
    .insert(organizations)
    .values({
      id: input.id ?? newId("org"),
      name: input.name,
      slug: input.slug,
      seatLimit: input.seatLimit ?? null,
      plan: input.plan ?? null,
      ownerId: input.ownerId ?? null,
      deletedAt: null,
      createdAt: toIsoTimestamp(new Date()),
    })
    .returning()
    .get();
  return toOrganization(row);
}

export function getOrganizationSync(orgId: OrgId): Organization | null {
  const row = getDb().select().from(organizations).where(eq(organizations.id, orgId)).get();
  return row ? toOrganization(row) : null;
}

export function isOrganizationDeletedSync(orgId: OrgId): boolean {
  const org = getOrganizationSync(orgId);
  return !org || org.deletedAt !== null;
}

export function deleteOrganizationSync(orgId: OrgId, now = new Date()): Organization | null {
  const stamp = toIsoTimestamp(now);
  const row = getDb()
    .update(organizations)
    .set({ deletedAt: stamp })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();
  clearDefaultOrgSync(orgId);
  return row ? toOrganization(row) : null;
}

