import { and, eq, isNull } from "drizzle-orm";

import { newId } from "@/lib/ids";
import { getDb } from "@/server/db/client";
import { members, organizations, sessions } from "@/server/db/schema";
import type { OrgId, SessionId, UserId } from "@/types/common";

export type Session = {
  id: SessionId;
  userId: UserId;
  defaultOrgId: OrgId | null;
};

function toSession(row: typeof sessions.$inferSelect): Session {
  return {
    id: row.id,
    userId: row.userId,
    defaultOrgId: row.defaultOrgId,
  };
}

export function insertSessionSync(input: {
  id?: SessionId;
  userId: UserId;
  defaultOrgId?: OrgId | null;
}): Session {
  const row = getDb()
    .insert(sessions)
    .values({
      id: input.id ?? newId("ses"),
      userId: input.userId,
      defaultOrgId: input.defaultOrgId ?? null,
    })
    .returning()
    .get();
  return toSession(row);
}

export function listSessionsForUserSync(userId: UserId): Session[] {
  return getDb().select().from(sessions).where(eq(sessions.userId, userId)).all().map(toSession);
}

export function updateSessionDefaultSync(sessionId: SessionId, orgId: OrgId | null): void {
  getDb().update(sessions).set({ defaultOrgId: orgId }).where(eq(sessions.id, sessionId)).run();
}

function fallbackOrgSync(userId: UserId, avoidOrgId: OrgId | null): OrgId | null {
  const rows = getDb()
    .select({ orgId: members.orgId, joinedAt: members.joinedAt })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(and(eq(members.userId, userId), eq(members.status, "active"), isNull(organizations.deletedAt)))
    .all();
  const candidates = rows
    .filter((row) => row.orgId !== avoidOrgId)
    .sort((a, b) => (a.joinedAt < b.joinedAt ? -1 : a.joinedAt > b.joinedAt ? 1 : 0));
  return candidates[0]?.orgId ?? null;
}

/** Sessions that were opening this workspace move to another live membership. */
export function retargetUserSessionsSync(userId: UserId, orgId: OrgId): void {
  const fallback = fallbackOrgSync(userId, orgId);
  const rows = getDb()
    .select()
    .from(sessions)
    .where(and(eq(sessions.userId, userId), eq(sessions.defaultOrgId, orgId)))
    .all();
  for (const row of rows) {
    updateSessionDefaultSync(row.id, fallback);
  }
}

/** Drop a deleted workspace from every session that was opening it. */
export function clearDefaultOrgSync(orgId: OrgId): void {
  const rows = getDb().select().from(sessions).where(eq(sessions.defaultOrgId, orgId)).all();
  for (const row of rows) {
    updateSessionDefaultSync(row.id, fallbackOrgSync(row.userId, orgId));
  }
}

export function resolveDefaultOrgSync(session: Session): OrgId | null {
  if (session.defaultOrgId) {
    const stillValid = getDb()
      .select({ orgId: members.orgId })
      .from(members)
      .innerJoin(organizations, eq(organizations.id, members.orgId))
      .where(
        and(
          eq(members.userId, session.userId),
          eq(members.orgId, session.defaultOrgId),
          eq(members.status, "active"),
          isNull(organizations.deletedAt),
        ),
      )
      .get();
    if (stillValid) return session.defaultOrgId;
  }
  const fallback = fallbackOrgSync(session.userId, session.defaultOrgId);
  if (session.defaultOrgId !== fallback) {
    updateSessionDefaultSync(session.id, fallback);
  }
  return fallback;
}

