  const row = getDb()
    .select()
    .from(members)
    .where(and(orgPredicate(members.orgId, orgId), eq(members.userId, userId)))
    .get();
  return row ? toMember(row) : null;
}

export function findMemberByIdSync(memberId: MemberId): Member | null {
  const row = getDb().select().from(members).where(eq(members.id, memberId)).get();
  return row ? toMember(row) : null;
}

export function findActiveMemberByEmailSync(orgId: OrgId, email: string): Member | null {
  const normalized = normalizeEmail(email);
  const row = getDb()
    .select({ member: members })
    .from(members)
    .leftJoin(users, eq(users.id, members.userId))
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        sql`lower(coalesce(${members.email}, ${users.email}, '')) = ${normalized}`,
      ),
    )
    .get();
  return row ? toMember(row.member) : null;
}

export function listActiveMembersSync(orgId: OrgId): Member[] {
  return getDb()
    .select()
    .from(members)
    .where(and(orgPredicate(members.orgId, orgId), eq(members.status, "active")))
    .all()
    .map(toMember);
}

export function countActiveMembersSync(orgId: OrgId): number {
  const row = getDb()
    .select({ value: count() })
    .from(members)
    .where(and(orgPredicate(members.orgId, orgId), eq(members.status, "active")))
    .get();
  return Number(row?.value ?? 0);
}

export function reactivateMemberSync(
  memberId: MemberId,
  input: { role: MemberRole; invitedBy: UserId | null; email?: string | null; joinedAt?: Date },
): Member {
  const stamp = toIsoTimestamp(input.joinedAt ?? new Date());
  const row = getDb()
    .update(members)
    .set({
      role: input.role,
      status: "active",
      invitedBy: input.invitedBy,
      joinedAt: stamp,
      removedAt: null,
      email: input.email ? normalizeEmail(input.email) : undefined,
    })
    .where(eq(members.id, memberId))
    .returning()
    .get();
  return toMember(row);
}

export function removeMemberSync(orgId: OrgId, userId: UserId): Member | null {
  const existing = findMemberSync(orgId, userId);
  if (!existing) return null;
  if (existing.status !== "removed") {
    getDb()
      .update(members)
      .set({ status: "removed", removedAt: toIsoTimestamp(new Date()) })
      .where(eq(members.id, existing.id))
      .run();
  }
  retargetUserSessionsSync(userId, orgId);
  return findMemberSync(orgId, userId);
}

export async function removeMember(orgId: OrgId, userId: UserId): Promise<Member | null> {
  return removeMemberSync(orgId, userId);
}

import { and, eq, isNull } from "drizzle-orm";

import { newId } from "@/lib/ids";
import { toIsoTimestamp } from "@/lib/time";
import { getDb } from "@/server/db/client";
import { members, notifications, organizations } from "@/server/db/schema";
import { findMemberSync, listActiveMembersSync } from "@/server/repositories/member-repository";
import { getOrganizationSync } from "@/server/repositories/organization-repository";
import type { NotificationId, OrgId, UserId } from "@/types/common";

export type Notification = {
  id: NotificationId;
  orgId: OrgId;
  userId: UserId;
  kind: string;
  payload: string;
  createdAt: string;
  readAt: string | null;
};

function toNotification(row: typeof notifications.$inferSelect): Notification {
  return {
    id: row.id,
    orgId: row.orgId,
    userId: row.userId,
    kind: row.kind,
    payload: row.payload,
    createdAt: row.createdAt,
    readAt: row.readAt,
  };
}

export function insertNotificationSync(input: {
  orgId: OrgId;
  userId: UserId;
  kind: string;
  payload?: unknown;
}): Notification | null {
  const org = getOrganizationSync(input.orgId);
  if (!org || org.deletedAt) return null;
  const member = findMemberSync(input.orgId, input.userId);
  if (!member || member.status !== "active") return null;
  const row = getDb()
    .insert(notifications)
    .values({
      id: newId("ntf"),
      orgId: input.orgId,
      userId: input.userId,
      kind: input.kind,
      payload: JSON.stringify(input.payload ?? {}),
      createdAt: toIsoTimestamp(new Date()),
      readAt: null,
    })
    .returning()
    .get();
  return toNotification(row);
}

export function listNotificationsForUserSync(userId: UserId): Notification[] {
  return getDb()
    .select({ notification: notifications })
    .from(notifications)
    .innerJoin(
      members,
      and(eq(members.orgId, notifications.orgId), eq(members.userId, notifications.userId)),
    )
    .innerJoin(organizations, eq(organizations.id, notifications.orgId))
    .where(and(eq(notifications.userId, userId), eq(members.status, "active"), isNull(organizations.deletedAt)))
    .all()
    .map((row) => toNotification(row.notification));
}

export function notifyMemberJoinedSync(orgId: OrgId, member: { id: string; userId: UserId; role: string }): void {
  const org = getOrganizationSync(orgId);
  const recipients = new Set<UserId>();
  if (org?.ownerId) recipients.add(org.ownerId);
  for (const owner of listActiveMembersSync(orgId)) {
    if (owner.role === "owner") recipients.add(owner.userId);
  }
  for (const userId of recipients) {
    insertNotificationSync({
      orgId,
      userId,
      kind: "member_joined",
      payload: { memberId: member.id, userId: member.userId, role: member.role },
    });
  }
}

import { DomainError, seatsTaken } from "@/server/errors";
import { countPendingInvitationsSync } from "@/server/repositories/invitation-repository";
import { countActiveMembersSync } from "@/server/repositories/member-repository";
import {
  getOrganizationSync,
  resolveSeatLimit,
  type Organization,
} from "@/server/repositories/organization-repository";
import type { OrgId } from "@/types/common";

export type SeatUsage = {
  members: number;
  pending: number;
  used: number;
  limit: number;
};

export function getSeatUsageSync(orgId: OrgId): SeatUsage {
  const org = getOrganizationSync(orgId);
  const members = countActiveMembersSync(orgId);
  const pending = countPendingInvitationsSync(orgId);
  return {
    members,
    pending,
    used: members + pending,
    limit: org ? resolveSeatLimit(org) : 0,
  };
}

export async function getSeatUsage(orgId: OrgId): Promise<SeatUsage> {
  return getSeatUsageSync(orgId);
}

export function assertSeatsAvailableSync(orgId: OrgId, additional: number): Organization {
  const org = getOrganizationSync(orgId);
  if (!org || org.deletedAt) {
    throw new DomainError("workspace_deleted", "This workspace has been deleted");
  }
  const used = countActiveMembersSync(orgId) + countPendingInvitationsSync(orgId);
  if (used + additional > resolveSeatLimit(org)) throw seatsTaken();
  return org;
}

import { INVITATION_VALID_DAYS } from "@/config/invitations";
import { normalizeEmail } from "@/lib/email";
import { transaction } from "@/server/db/client";
import { DomainError } from "@/server/errors";
import {
  findInvitationByTokenSync,
  findPendingInvitationByEmailSync,
  getInvitationSync,
  insertInvitationSync,
  invitationState,
  listInvitationsSync,
  markInvitationAcceptedSync,
  revokeInvitationSync,
} from "@/server/repositories/invitation-repository";
import {
  findActiveMemberByEmailSync,
  findMemberSync,
  insertMemberSync,
  reactivateMemberSync,
} from "@/server/repositories/member-repository";
import { isOrganizationDeletedSync } from "@/server/repositories/organization-repository";
import { notifyMemberJoinedSync } from "@/server/repositories/notification-repository";
import { findUserByEmailSync, findUserSync } from "@/server/repositories/user-repository";
import { assertSeatsAvailableSync } from "@/server/services/seats";
import type { InvitationId, OrgId, UserId } from "@/types/common";
import type { Invitation, InvitationState, Member, MemberRole } from "@/types/member";

export type Actor = {
  userId: UserId;
  orgId?: OrgId;
  email?: string;
};

export type InviteDraft = {
  email: string;
  role: MemberRole;
};

export type InvitationView = Invitation & { state: InvitationState };

function requireLiveInvitation(invitation: Invitation | null, orgId?: OrgId): Invitation {
  if (!invitation || (orgId && invitation.orgId !== orgId)) {
    throw new DomainError("not_found", "Invitation not found");
  }
  return invitation;
}

function accountEmail(actor: { userId: UserId; email?: string }): string {
  const user = findUserSync(actor.userId);
  if (user) return user.email;
  if (actor.email) return actor.email;
  throw new DomainError("not_found", "Account not found");
}

function inviteManySync(actor: Actor, orgId: OrgId, drafts: InviteDraft[]): Invitation[] {
  if (isOrganizationDeletedSync(orgId)) {
    throw new DomainError("workspace_deleted", "This workspace has been deleted");
  }
  const normalized = drafts.map((draft) => ({
    email: normalizeEmail(draft.email),
    role: draft.role,
  }));
  if (normalized.some((draft) => draft.email.length === 0 || draft.role.trim().length === 0)) {
    throw new DomainError("invalid", "That batch contains an empty address or role");
  }
  const seen = new Set<string>();
  for (const draft of normalized) {
    if (seen.has(draft.email)) {
      throw new DomainError("duplicate", "That batch names the same address more than once");
    }
    seen.add(draft.email);
  }
  for (const draft of normalized) {
    if (findActiveMemberByEmailSync(orgId, draft.email)) {
      throw new DomainError("already_member", "That address belongs to a current member");
    }
    if (findPendingInvitationByEmailSync(orgId, draft.email)) {
      throw new DomainError("pending", "That address already has a pending invitation");
    }
  }
  assertSeatsAvailableSync(orgId, normalized.length);
  return normalized.map((draft) =>
    insertInvitationSync(orgId, {
      email: draft.email,
      role: draft.role,
      expiresInDays: INVITATION_VALID_DAYS,
      invitedBy: actor.userId,
    }),
  );
}

export async function inviteMember(
  actor: Actor,
  input: { orgId?: OrgId; email: string; role: MemberRole },
): Promise<Invitation> {
  const orgId = input.orgId ?? actor.orgId;
  if (!orgId) throw new DomainError("invalid", "A workspace is required");
  return transaction(() => inviteManySync(actor, orgId, [{ email: input.email, role: input.role }])[0]);
}

export async function inviteMembers(
  actor: Actor,
  input:
    | { orgId?: OrgId; invitations: InviteDraft[] }
    | { orgId?: OrgId; emails: string[]; role: MemberRole },
): Promise<Invitation[]> {
  const orgId = input.orgId ?? actor.orgId;
  if (!orgId) throw new DomainError("invalid", "A workspace is required");
  const drafts =
    "emails" in input
      ? input.emails.map((email) => ({ email, role: input.role }))
      : input.invitations;
  return transaction(() => inviteManySync(actor, orgId, drafts));
}

export async function resendInvitation(actor: Actor, invitationId: InvitationId): Promise<Invitation> {
  return transaction(() => {
    const orgId = actor.orgId;
    const previous = requireLiveInvitation(getInvitationSync(invitationId), orgId);
    if (previous.acceptedAt) {
      throw new DomainError("accepted", "This invitation has already been used");
    }
    if (!previous.revokedAt) revokeInvitationSync(previous.orgId, previous.id);
    const [created] = inviteManySync(actor, previous.orgId, [
      { email: previous.email, role: previous.role },
    ]);
    return created;
  });
}

export async function revokeInvitation(actor: Actor, invitationId: InvitationId): Promise<Invitation> {
  return transaction(() => {
    const existing = requireLiveInvitation(getInvitationSync(invitationId), actor.orgId);
    if (existing.acceptedAt) {
      throw new DomainError("accepted", "This invitation has already been used");
    }
    return revokeInvitationSync(existing.orgId, existing.id);
  });
}

function refuseUnlessAcceptable(invitation: Invitation, now: Date): void {
  if (isOrganizationDeletedSync(invitation.orgId)) {
    throw new DomainError("workspace_deleted", "This workspace has been deleted");
  }
  if (invitation.acceptedAt) {
    throw new DomainError("accepted", "This invitation has already been used");
  }
  if (invitation.revokedAt) {
    throw new DomainError("revoked", "This invitation has been revoked");
  }
  if (invitationState(invitation, now) === "expired") {
    throw new DomainError("expired", "This invitation has expired");
  }
}

function memberFromInvitationSync(invitation: Invitation, userId: UserId, email: string): Member {
  const existing = findMemberSync(invitation.orgId, userId);
  if (existing?.status === "active") return existing;
  if (existing) {
    return reactivateMemberSync(existing.id, {
      role: invitation.role,
      invitedBy: invitation.invitedBy,
      email,
      joinedAt: new Date(),
    });
  }
  const linked = findUserByEmailSync(email);
  return insertMemberSync({
    orgId: invitation.orgId,
    userId: linked?.id === userId ? userId : userId,
    role: invitation.role,
    invitedBy: invitation.invitedBy,
    email,
  });
}

export async function acceptInvitation(
  actor: { userId: UserId; email?: string },
  token: string,
): Promise<Member> {
  return transaction(() => {
    const now = new Date();
    const invitation = findInvitationByTokenSync(token);
    if (!invitation) throw new DomainError("not_found", "Invitation not found");
    refuseUnlessAcceptable(invitation, now);
    const email = accountEmail(actor);
    if (normalizeEmail(email) !== normalizeEmail(invitation.email)) {
      throw new DomainError("email_mismatch", "This invitation was sent to a different email address");
    }
    const current = findInvitationByTokenSync(token);
    if (!current) throw new DomainError("not_found", "Invitation not found");
    refuseUnlessAcceptable(current, now);
    const member = memberFromInvitationSync(current, actor.userId, email);
    const accepted = markInvitationAcceptedSync(current.id, now);
    if (!accepted) throw new DomainError("accepted", "This invitation has already been used");
    notifyMemberJoinedSync(current.orgId, member);
    return member;
  });
}

export async function listInvitations(orgId: OrgId): Promise<InvitationView[]> {
  const now = new Date();
  return listInvitationsSync(orgId).map((invitation) => ({
    ...invitation,
    state: invitationState(invitation, now),
  }));
}

export async function getInvitationByToken(token: string): Promise<InvitationView | null> {
  const invitation = findInvitationByTokenSync(token);
  if (!invitation) return null;
  return { ...invitation, state: invitationState(invitation) };
}

import { transaction } from "@/server/db/client";
import { DomainError } from "@/server/errors";
import {
  findMemberSync,
  listActiveMembersSync,
  removeMemberSync,
} from "@/server/repositories/member-repository";
import { deleteOrganizationSync } from "@/server/repositories/organization-repository";
import {
  listSessionsForUserSync,
  resolveDefaultOrgSync,
  type Session,
} from "@/server/repositories/session-repository";
import type { OrgId, UserId } from "@/types/common";
import type { Member } from "@/types/member";

export async function listMembers(orgId: OrgId): Promise<Member[]> {
  return listActiveMembersSync(orgId);
}

export async function assertActiveMember(orgId: OrgId, userId: UserId): Promise<Member> {
  const member = findMemberSync(orgId, userId);
  if (!member || member.status !== "active") {
    throw new DomainError("not_member", "You are not a member of this workspace");
  }
  return member;
}

export async function removeMember(orgId: OrgId, userId: UserId): Promise<Member> {
  return transaction(() => {
    const removed = removeMemberSync(orgId, userId);
    if (!removed) throw new DomainError("not_member", "You are not a member of this workspace");
    return removed;
  });
}

export async function deleteOrganization(orgId: OrgId): Promise<void> {
  transaction(() => {
    deleteOrganizationSync(orgId);
  });
}

export async function resolveOpeningWorkspace(session: Session): Promise<OrgId | null> {
  return resolveDefaultOrgSync(session);
}

export async function openingWorkspaceForUser(userId: UserId): Promise<OrgId | null> {
  const sessions = listSessionsForUserSync(userId);
  if (sessions.length === 0) return null;
  return resolveDefaultOrgSync(sessions[0]);
}

import { listNotificationsForUserSync, type Notification } from "@/server/repositories/notification-repository";
import type { UserId } from "@/types/common";

export async function listNotifications(userId: UserId): Promise<Notification[]> {
  return listNotificationsForUserSync(userId);
}

import { isNull } from "drizzle-orm";

import { getDb } from "@/server/db/client";
import { organizations } from "@/server/db/schema";
import { listActiveMembersSync } from "@/server/repositories/member-repository";
import type { OrgId, UserId } from "@/types/common";

export type DigestDelivery = {
  orgId: OrgId;
  recipientIds: UserId[];
};

/** Daily digest goes only to current members of a workspace that still exists. */
export function listDigestRecipientsSync(orgId: OrgId): UserId[] {
  const org = getDb().select().from(organizations).where(isNull(organizations.deletedAt)).all().find((row) => row.id === orgId);
  if (!org) return [];
  return listActiveMembersSync(orgId).map((member) => member.userId);
}

export async function listDigestRecipients(orgId: OrgId): Promise<UserId[]> {
  return listDigestRecipientsSync(orgId);
}

export async function runDailyDigest(): Promise<DigestDelivery[]> {
  const orgs = getDb().select().from(organizations).where(isNull(organizations.deletedAt)).all();
  return orgs.map((org) => ({
    orgId: org.id,
    recipientIds: listDigestRecipientsSync(org.id),
  }));
}

import { runDailyDigest } from "@/server/jobs/digest";

export async function GET() {
  const deliveries = await runDailyDigest();
  return Response.json({ deliveries });
}

export async function POST() {
  return GET();
}

import type { Invitation } from "@/types/member";

export function buildInvitationEmail(invitation: Invitation): { to: string; subject: string; text: string } {
  return {
    to: invitation.email,
    subject: "You've been invited",
    text: `You have been invited with the ${invitation.role} role. This link is valid for 14 days.`,
  };
}

