    .where(and(eq(sessions.userId, userId), eq(sessions.defaultOrgId, orgId)))
    .all();
  for (const row of rows) {
    updateSessionDefaultSync(row.id, fallback);
  }
}

/** Drop a deleted workspace from every session that was opening it. */
export function clearDefaultOrgSync(orgId: OrgId): void {
  const rows = getDb().select().from(sessions).where(eq(sessions.defaultOrgId, orgId)).all();
  for (const row of rows) {
    updateSessionDefaultSync(row.id, fallbackOrgSync(row.userId, orgId));
  }
}

export function resolveDefaultOrgSync(session: Session): OrgId | null {
  if (session.defaultOrgId) {
    const stillValid = getDb()
      .select({ orgId: members.orgId })
      .from(members)
      .innerJoin(organizations, eq(organizations.id, members.orgId))
      .where(
        and(
          eq(members.userId, session.userId),
          eq(members.orgId, session.defaultOrgId),
          eq(members.status, "active"),
          isNull(organizations.deletedAt),
        ),
      )
      .get();
    if (stillValid) return session.defaultOrgId;
  }
  const fallback = fallbackOrgSync(session.userId, session.defaultOrgId);
  if (session.defaultOrgId !== fallback) {
    updateSessionDefaultSync(session.id, fallback);
  }
  return fallback;
}
