    throw new DomainError("invalid", "That batch contains an empty address or role");
  }
  const seen = new Set<string>();
  for (const draft of normalized) {
    if (seen.has(draft.email)) {
      throw new DomainError("duplicate", "That batch names the same address more than once");
    }
    seen.add(draft.email);
