export function claimEmptySessionsSync(userId: UserId, orgId: OrgId): void {
  const rows = getDb()
    .select()
    .from(sessions)
    .where(and(eq(sessions.userId, userId), isNull(sessions.defaultOrgId)))
    .all();
  for (const row of rows) updateSessionDefaultSync(row.id, orgId);
